public static IWeaponFactory Factory(Action<IBuilder> configure) {
    var map = new Dictionary<WeaponType, Func<Weapon>>();
    configure(new Builder(map));                        // Add(key, () => new Sword())
    return key => map.TryGetValue(key, out var make)
        ? make()
        : throw new KeyNotFoundException($"unknown weapon: {key}");
}
